import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"57、【巽】 巽下巽上","description":"周易口訣義 - 57、【巽】 巽下巽上","frontmatter":{"title":"57、【巽】 巽下巽上","description":"周易口訣義 - 57、【巽】 巽下巽上"},"headers":[],"relativePath":"classics/koujueyi/059.md","filePath":"classics/koujueyi/059.md"}'),r={name:"classics/koujueyi/059.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_57、【巽】-巽下巽上" tabindex="-1">57、【巽】 巽下巽上 <a class="header-anchor" href="#_57、【巽】-巽下巽上" aria-label="Permalink to “57、【巽】 巽下巽上”">​</a></h1><p>彖曰：重巽以申命。剛巽乎中正而志行，柔皆順乎剛，是以「小亨，利有攸往，利見大人」。</p><p>象曰：隨風，巽，君子以申命行事。</p><p>初六：進退，利武人之貞。</p><p>象曰：「進退」，志疑也。「利武人之貞」，志治也。</p><p>九二：巽在床下，用史巫紛若，吉，無咎。</p><p>象曰：「紛若」之「吉」，得中也。</p><p>九三：頻巽，吝。</p><p>象曰：「頻巽」之「吝」，志窮也。</p><p>六四：悔亡，田獲三品。</p><p>象曰：「田獲三品」，有功也。</p><p>九五：貞吉，悔亡，無不利，無初有終，先庚三日，後庚三日，吉。</p><p>象曰：九五之「吉」，位正中也。</p><p>上九：巽在床下，喪其資斧，貞兇。</p><p>象曰：「巽在床下」，上窮也。「喪其資斧」，正乎兇也。</p><p>解讀</p><p>「巽小亨」者，「巽」是卑順之名，和入為義，故謂之「巽」也。夫人用巽，必須恭儉莊敬，進退合宜，若過於卑巽，逾尊卑之分，敬恭不合禮，即所通非大，故曰「小亨」也。「利有攸往」者，巽順以行，物不違拒，故曰「利有攸往」也。「利見大人」者，人用巽順，即無往不利，大人用巽，其道愈隆，巽順之美，上下皆須之，故曰「利見大人」也。象曰「隨風，巽」者，按說卦雲：「巽，入也。」風之所入，物無不順，風相隨而行，故曰「隨風，巽」也。君子以申命行事者，風行草偃，亦有王者風教行於天下意，故君子象此，申其命令，行其政教之事也。</p><p>「初六，進退，利武人之貞」者，出令之初，人未從化，心懷猶豫，進退遲疑；申命之初，人未信服，成命齊邦，莫過威武以整齊之，故曰「進退，利武人之貞」也。</p><p>「九二，巽在床下，用史巫紛若，吉，無咎」者，史謂祝史，巫謂巫覡，皆是接事鬼神之人。九二處巽之中，在下位，而以陽居陰，卑巽而順，故曰「巽在床下」者，卑謙過甚，失於正道，咎過生焉。然鬼神無形，所在怠慢，九二卑恭如是，事神祗而獲多福，故曰「用史巫紛若，吉，無咎」也。紛者，盛多之貌也。</p><p>「九三，頻巽，吝」者，頻是頻蹙不樂之貌也。九三體剛居正，為四所乘，志意窮屈，不得舒暢，故懷頻蹙，即是鄙吝之道，故曰「頻巽，吝」。</p><p>「六四，悔亡，田獲三品」者，六四乘九三之剛，所以有悔；然得位乘五，上奉君命，所以「悔亡」。親近至尊，即是權臣，以斯行命，必有功勞，譬之田獵而獲三品之物，故曰「田獲三品」也。一曰乾豆為豆實，以奉宗廟；二曰賓客以助君明目達聰；三曰充君之庖廚，供君之費也。</p><p>九五，貞吉，悔亡，無不利，無初有終。「先庚三日，後庚三日，吉」者，五以剛居位，違于謙巽，故有憂悔；能用中正以宣命令，人不敢違，所以「悔亡」而「無不利」也。初施命令，新用剛直，人未從化，故曰「無初」；以中正之德，宣佈命令，人漸從化，故曰「有終」也。申命令謂之庚。以人迷既久，不可卒然而理，故先申三日，慇懃勸諭，使其變惡從善。令著之後，復再申三日，人若不從，即當誅罰，民服其罪，所以獲吉，故曰「先庚三日，後庚三日，吉」也。</p><p>上九，巽在床下，喪其資斧，貞兇者，處巽之極，言巽過甚，似巽於床下。斧者，是斬斷之物，喻決斷威制。今既處上，固合威斷，臨下而乃過於謙，即是喪其威斷，是正道之失，故曰「喪其資斧，貞兇」也。</p>',23)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
